import 'dart:convert';
import 'dart:io';

const _valuesFileName = "site.json";
const _templatesDirectoryName = "templates";
const _publicDirectoryName = "public";
const _germanDirectoryPrefix = "de/";
const _germanLanguageCode = "de";
const _englishLanguageCode = "en";
const _generatedNotice =
    "<!-- Generated by website/build_site.dart from website/templates and website/site.json. "
    "Edit those and rebuild; changes made here are overwritten. -->";
const _escape = HtmlEscape(HtmlEscapeMode.attribute);

final _sectionPattern = RegExp(
  r"^[ \t]*\{\{#([\w.]+)\}\}\n([\s\S]*?)^[ \t]*\{\{/\1\}\}\n",
  multiLine: true,
);
final _valuePattern = RegExp(r"\{\{([\w.]+)\}\}");

void main() {
  final websiteDirectory = File.fromUri(Platform.script).parent;
  final values = jsonDecode(
    File("${websiteDirectory.path}/$_valuesFileName").readAsStringSync(),
  );
  final templatesDirectory = Directory("${websiteDirectory.path}/$_templatesDirectoryName");
  final templates = templatesDirectory.listSync(recursive: true).whereType<File>().toList()
    ..sort((first, second) => first.path.compareTo(second.path));
  for (final template in templates) {
    final relativePath = template.path.substring(templatesDirectory.path.length + 1);
    final language = relativePath.startsWith(_germanDirectoryPrefix)
        ? _germanLanguageCode
        : _englishLanguageCode;
    final html = _render(template.readAsStringSync(), values, language, relativePath);
    final output = File("${websiteDirectory.path}/$_publicDirectoryName/$relativePath");
    output.parent.createSync(recursive: true);
    output.writeAsStringSync(html.replaceFirst("<html", "$_generatedNotice\n<html"));
    stdout.writeln("Built $_publicDirectoryName/$relativePath");
  }
}

String _render(String template, Object? values, String language, String path) {
  final withSections = template.replaceAllMapped(
    _sectionPattern,
    (match) => _isFilled(_lookup(values, match[1]!, language, path)) ? match[2]! : "",
  );
  final rendered = withSections.replaceAllMapped(
    _valuePattern,
    (match) => _escape.convert(_text(_lookup(values, match[1]!, language, path), match[1]!, path)),
  );
  if (rendered.contains("{{")) {
    throw FormatException("Unresolved template syntax in $path.");
  }
  return rendered;
}

Object? _lookup(Object? values, String key, String language, String path) {
  var value = values;
  for (final part in key.split(".")) {
    if (value is! Map<String, Object?> || !value.containsKey(part)) {
      throw FormatException("Unknown value \"$key\" in $path.");
    }
    value = value[part];
  }
  return switch (value) {
    final Map<String, Object?> localized when localized.containsKey(language) =>
      localized[language],
    _ => value,
  };
}

bool _isFilled(Object? value) => switch (value) {
  final String text => text.isNotEmpty,
  final bool flag => flag,
  _ => false,
};

String _text(Object? value, String key, String path) => switch (value) {
  final String text => text,
  _ => throw FormatException("Value \"$key\" in $path is not text."),
};
